package br.gov.dere.api; import br.gov.dere.application.csv.DereCsvConverter; import br.gov.dere.application.d1001.D1001XmlGenerator; import br.gov.dere.domain.contributor.D1001; import br.gov.dere.integration.xml.XmlSupport; import java.time.LocalDate; import java.util.List; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/validation") public class ValidationController {private final DereCsvConverter csv=new DereCsvConverter();private final D1001XmlGenerator gen=new D1001XmlGenerator(); @PostMapping("/csv-to-xml") public Result csv(@RequestBody String body)throws Exception{var d=csv.fromCsv(body);var xml=gen.generate(d);var url=getClass().getResource("/dere/schemas/nota_2026_001/xsd/evtInfoContrib-v1_0_1.xsd");XmlSupport.validate(xml,url);return new Result(true,xml,csv.toCsv(d),List.of());} @PostMapping("/xml-to-csv") public String xml(@RequestBody String body)throws Exception{return csv.xmlToCsv(body);} public record Result(boolean valid,String xml,String csv,List<String> errors){} }
